<?php require_once '../config.php'; login_required('admin'); $msg='';$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']);$author=trim($_POST['author']);$category=trim($_POST['category']);$isbn=trim($_POST['isbn']);$qty=(int)$_POST['quantity']; if($qty<1)$error='Quantity must be 1 or more.'; else { $q=mysqli_prepare($conn,'INSERT INTO books(title,author,category,isbn,quantity,available) VALUES(?,?,?,?,?,?)'); mysqli_stmt_bind_param($q,'ssssii',$title,$author,$category,$isbn,$qty,$qty); if(mysqli_stmt_execute($q))$msg='Book added.';else$error='ISBN already exists.'; }} ?><!doctype html><html><head><title>Add Book</title><link rel="stylesheet" href="../assets/css/admin/add_book.css"><link rel="stylesheet" href="../assets/css/admin/sidebar.css"></head><body><div class="layout"><?php include 'sidebar.php';?><main class="main"><h1>Add Book</h1><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><div class="panel"><form method="post"><input name="title" placeholder="Book Title" required><input name="author" placeholder="Author" required><input name="category" placeholder="Category" required><input name="isbn" placeholder="ISBN"><input type="number" name="quantity" min="1" placeholder="Quantity" required><button class="btn">Save Book</button></form></div></main></div></body></html>
